create table public.property_qr_tokens (id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties_v2(id) on delete restrict, token_hash text not null unique, status public.record_status not null default 'active', created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), expires_at timestamptz, revoked_at timestamptz); alter table public.property_qr_tokens enable row level security;
